from pathlib import Path

path = Path(__file__).with_name('apply_tiered_safety_fix.py')
text = path.read_text(encoding='utf-8')
old64 = ''
new64 = ''

lines = text.splitlines()
indices = [i for i, line in enumerate(lines) if line.startswith("replace_exact('src/HelpSys.Desktop/MainWindow.xaml'")]
if not indices:
    raise RuntimeError('No MainWindow.xaml patch call found')
i = indices[0]
lines[i] = f"replace_exact('src/HelpSys.Desktop/MainWindow.xaml', '{old64}', '{new64}', 1)"
path.write_text('\n'.join(lines) + '\n', encoding='utf-8', newline='\n')
print('XAML patch anchor repaired')
